<script setup lang="ts">
import type { RouteTemplate, Station, Unit, Page } from '~/utils/types'
const { unitIds }=useSession(); const api=useApi(); const templates=ref<RouteTemplate[]>([]); const stations=ref<Station[]>([]); const units=ref<Unit[]>([]); const loading=ref(false);const saving=ref(false);const error=ref<unknown>();const message=ref('');const edit=ref<RouteTemplate|null>(null)
const form=reactive({name:'',origin_unit_id:'',station_ids:['','']})
function label(id:string){return stations.value.find(s=>s.id===id)?.name||id}
async function load(){loading.value=true;error.value=undefined;try{const values=await Promise.all([api.get<RouteTemplate[]>('/route-templates'),api.get<Page<Station>>('/stations'),api.get<Page<Unit>>('/units?limit=100')]);templates.value=values[0];stations.value=values[1].items;units.value=values[2].items.filter(u=>unitIds.value.includes(u.id));if(!form.origin_unit_id)form.origin_unit_id=units.value[0]?.id||''}catch(e){error.value=e}finally{loading.value=false}}
function select(t?:RouteTemplate){edit.value=t||null;form.name=t?.name||'';form.origin_unit_id=t?.origin_unit_id||units.value[0]?.id||'';form.station_ids=t?[...t.station_ids]:['',''];message.value=''}
function move(index:number,by:number){const route=[...form.station_ids];[route[index],route[index+by]]=[route[index+by]!,route[index]!];form.station_ids=route}
async function save(){saving.value=true;error.value=undefined;message.value='';try{const body={name:form.name.trim(),origin_unit_id:form.origin_unit_id,station_ids:form.station_ids};if(edit.value)await api.command(`/route-templates/${edit.value.id}`,{...body,expected_version:edit.value.version},'PUT');else await api.command('/route-templates',body);select();message.value='บันทึกเวอร์ชันเส้นทางแล้ว เส้นทางหนังสือเดิมคงเดิม';await load()}catch(e){error.value=e}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="page-head"><div><h1>Route Template</h1><p>กำหนดลำดับ Station รวมจุดรับคืนต้นทาง หนังสือแต่ละเรื่องจะเก็บสำเนาเส้นทางของตน</p></div></div><Feedback :error="error" :message="message" /><div class="split"><section class="panel"><div class="page-head"><h2>เส้นทางของหน่วยงาน</h2><button class="text-link" @click="load">โหลดล่าสุด</button></div><UProgress v-if="loading" /><div v-if="!templates.length&&!loading" class="empty">ยังไม่มี Route Template สร้างเส้นทางก่อนลงทะเบียนหนังสือ</div><article v-for="t in templates" :key="`${t.id}:${t.version}`" class="timeline"><div class="actions"><h3>{{t.name}}</h3><span class="status">เวอร์ชัน {{t.version}}</span></div><ol class="route-steps"><li v-for="(id,i) in t.station_ids" :key="i"><small>จุดที่ {{i+1}}</small>{{label(id)}}</li></ol><button type="button" class="text-link" @click="select(t)">สร้างเวอร์ชันใหม่</button></article></section><form class="panel" @submit.prevent="save"><h2>{{edit?'สร้างเวอร์ชันใหม่':'สร้างเส้นทาง'}}</h2><div class="field"><label for="template-name">ชื่อเส้นทาง</label><input id="template-name" v-model="form.name" required maxlength="255" /></div><div class="field"><label for="template-origin">หน่วยงานต้นทาง</label><select id="template-origin" v-model="form.origin_unit_id" required :disabled="!!edit"><option disabled value="">เลือกหน่วยงาน</option><option v-for="u in units" :key="u.id" :value="u.id">{{u.name}}</option></select></div><div v-for="(_,i) in form.station_ids" :key="i" class="field"><label :for="`route-${i}`">จุดที่ {{i+1}} {{i===0?'· ต้นทาง':i===form.station_ids.length-1?'· รับคืนต้นทาง':''}}</label><select :id="`route-${i}`" v-model="form.station_ids[i]" required><option disabled value="">เลือก Station</option><option v-for="s in stations" :key="s.id" :value="s.id">{{s.name}}</option></select><div class="actions"><button type="button" class="text-link" :disabled="i===0" @click="move(i,-1)">เลื่อนขึ้น</button><button type="button" class="text-link" :disabled="i===form.station_ids.length-1" @click="move(i,1)">เลื่อนลง</button><button v-if="form.station_ids.length>2" type="button" class="text-link" @click="form.station_ids.splice(i,1)">ลบจุดนี้</button></div></div><button type="button" class="button" @click="form.station_ids.push('')">เพิ่ม Station</button><p class="hint">Station เดิมปรากฏหลายจุดได้ แต่ละจุดจะมีรหัสขั้นตอนแยกกัน จุดสุดท้ายต้องเป็นต้นทาง</p><div class="actions"><button class="button primary" :disabled="saving||!units.length">{{saving?'กำลังบันทึก…':'บันทึกเส้นทาง'}}</button><button v-if="edit" type="button" class="button" @click="select()">ยกเลิกแก้ไข</button></div></form></div></template>
